create schema if not exists private;
revoke all on schema private from public,anon;
grant usage on schema private to authenticated;
alter function public.betalink_wallet_snapshot() set schema private;
alter function public.betalink_create_campaign(text,text,text,text,integer,integer) set schema private;
alter function public.betalink_create_group(text,text,boolean) set schema private;
alter function public.betalink_join_group(uuid) set schema private;
grant execute on function private.betalink_wallet_snapshot() to authenticated;
grant execute on function private.betalink_create_campaign(text,text,text,text,integer,integer) to authenticated;
grant execute on function private.betalink_create_group(text,text,boolean) to authenticated;
grant execute on function private.betalink_join_group(uuid) to authenticated;
create or replace function public.betalink_wallet_snapshot() returns table(balance integer,lifetime_earned integer,completed_support_tests integer) language sql security invoker set search_path=public,private,pg_temp as $$ select * from private.betalink_wallet_snapshot(); $$;
create or replace function public.betalink_create_campaign(p_app_name text,p_play_opt_in_url text,p_description text default '',p_category text default 'other',p_target_testers integer default 12,p_minimum_android_version integer default null) returns uuid language sql security invoker set search_path=public,private,pg_temp as $$ select private.betalink_create_campaign(p_app_name,p_play_opt_in_url,p_description,p_category,p_target_testers,p_minimum_android_version); $$;
create or replace function public.betalink_create_group(p_name text,p_description text default '',p_is_private boolean default false) returns uuid language sql security invoker set search_path=public,private,pg_temp as $$ select private.betalink_create_group(p_name,p_description,p_is_private); $$;
create or replace function public.betalink_join_group(p_group_id uuid) returns text language sql security invoker set search_path=public,private,pg_temp as $$ select private.betalink_join_group(p_group_id); $$;
revoke all on function public.betalink_wallet_snapshot() from public,anon;
revoke all on function public.betalink_create_campaign(text,text,text,text,integer,integer) from public,anon;
revoke all on function public.betalink_create_group(text,text,boolean) from public,anon;
revoke all on function public.betalink_join_group(uuid) from public,anon;
grant execute on function public.betalink_wallet_snapshot() to authenticated;
grant execute on function public.betalink_create_campaign(text,text,text,text,integer,integer) to authenticated;
grant execute on function public.betalink_create_group(text,text,boolean) to authenticated;
grant execute on function public.betalink_join_group(uuid) to authenticated;
create index if not exists betalink_wallet_ledger_campaign_idx on public.betalink_wallet_ledger(campaign_id);
create index if not exists betalink_wallet_ledger_group_idx on public.betalink_wallet_ledger(group_id);